INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-cgs-type-a-hec', 'Chinese Government Scholarship - Type A (HEC nomination, Pakistan)', 'CN', 'China Scholarship Council; nominated by HEC Pakistan', 'hec-cgsp', 'https://www.hec.gov.pk/english/scholarshipsgrants/lao/CGSP/Pages/Eligibility-Criteria.aspx', '["bachelor","master","phd"]', 'new', 'HEC page gives 75 seats (35 Bachelors, 25 Masters, 15 PhD). Coverage per CSC guide: tuition, free dormitory or accommodation subsidy, monthly stipend, comprehensive medical insurance. Stipend (as published): Undergraduates: CNY 2,500 per month; Master''s students/general scholars: CNY 3,000 per month; Doctoral students/senior scholars: CNY 3,500 per month (from CSC guide, not HEC page)', '{}', 'HEC scholarship portal, then CSC online system (Agency No. 5861, Embassy of PR China in Pakistan, Type A); embassy first-round review', 'HEC SCHOLARSHIP PORTAL DEADLINE: MONDAY, 05 JANUARY 2026 (04:00 PM PAKISTAN STANDARD TIME)', '2026/27', 'NEEDS_REVIEW', 0, '2026-10-25', 'HEC intro and Eligibility pages opened (raw text). Stipend amounts come from campuschina guide, not HEC. Cycle closed; 2027-28 HEC call not yet published. HEC Financial-Coverage and How-to-Apply pages not opened.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-cgs-csc-general', 'Chinese Government Scholarship (Bilateral / University Program) - CSC guide', 'CN', 'China Scholarship Council', 'campuschina-csc', 'https://www.campuschina.org/content/details3_74776.html', '["bachelor","master","phd"]', 'new', 'Tuition fees; free university dormitory or accommodation subsidy; monthly stipend; comprehensive medical insurance (CNY 800 per person per year). Stipend (as published): Undergraduates: CNY 2,500 per month; Master''s students/general scholars: CNY 3,000 per month; Doctoral students/senior scholars: CNY 3,500 per month', '{}', 'Bilateral Program via home-country dispatching agency (HEC/Chinese Embassy for Pakistan); University Program (Type B) directly via designated Chinese universities; online form on CSC system', NULL, NULL, 'NEEDS_REVIEW', 0, '2026-10-25', 'Raw page text read. No deadline on page (deadlines vary by agency/university). Page header date 2018 but content updated (CSCA).', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-cgs-type-b-tsinghua', 'Chinese Government Scholarship Type B - Tsinghua University (graduate)', 'CN', 'Tsinghua University / CSC', 'tsinghua-grad', 'https://yz.tsinghua.edu.cn/en/info/1027/1117.htm', '["master","phd"]', 'new', 'Full CGS covers tuition fees, free university dormitory or accommodation subsidy, stipend, and comprehensive medical insurance; partial CGS covers one or some items.', '{}', 'Direct to Tsinghua (pre-admission via yzbm.tsinghua.edu.cn), then CSC online system; university nominates to CSC', 'Applicants are highly recommended to apply before Mid-December, 2025 (please refer to the application deadline of each department or school)', '2026/27', 'NEEDS_REVIEW', 0, '2026-10-25', 'Opened via extraction tool; excerpts need verbatim check. Page says 2027 scholarship ''coming soon''; 2026 cycle deadline passed.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-tsinghua-ug-freshmen', 'Tsinghua University International Undergraduate Freshmen Scholarship', 'CN', 'Tsinghua University', 'tsinghua-ug', 'https://international.join-tsinghua.edu.cn/Admission1/Freshmen_Scholarships1.htm', '["bachelor"]', 'new', 'First-year support: full-tuition, half-tuition, or partial-tuition scholarships; later years may apply for other scholarships incl. Beijing Government Scholarship. About 45% of 2026 international freshmen received it.', '{}', 'Tsinghua undergraduate application system', NULL, NULL, 'NEEDS_REVIEW', 0, '2026-10-25', 'Deadline not on page. Same page says CGS Type A application period is usually November 2026 to April 2027 via local Chinese Embassy. Extraction tool used; verify verbatim.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-cgs-type-b-zju', 'Chinese Government Scholarship Type B - Zhejiang University', 'CN', 'Zhejiang University / CSC', 'zju-iczu', 'https://iczu.zju.edu.cn/admissionsen/2022/0530/c68995a2590720/page.htm', '["master","phd"]', 'new', 'Tuition waiver; free on-campus accommodation or allowance; stipend per relevant standard; comprehensive medical insurance. Stipend (as published): Stipend: Granted in accordance with the relevant standard', '{}', 'CSC online system (agency number 10335) plus ZJU online application system; RMB 800 application fee', 'December 31, 2025 (The deadline is Beijing Time and includes the day itself.)', '2026/27', 'NEEDS_REVIEW', 0, '2026-10-25', 'Extraction tool; verify verbatim. Cycle closed; 2027 guide not seen.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-zhejiang-gov-zju', 'Zhejiang Government Scholarship (new international postgraduates, ZJU)', 'CN', 'Zhejiang Provincial Government via Zhejiang University', 'zju-iczu', 'https://iczu.zju.edu.cn/admissionsen/2022/0530/c68995a2590722/page.htm', '["master","phd"]', 'new', 'The funding amount of this scholarship is RMB 30,000 yuan, and the funding period is one year; may reapply with excellent performance.', '{}', 'ZJU online application system plus scholarship application form and non-criminal record certificate', 'February 28, 2026 (The deadline is Beijing Time and includes the day itself.)', '2026/27', 'NEEDS_REVIEW', 0, '2026-10-25', 'Page does not say whether tuition is covered. Extraction tool; verify verbatim. Cycle closed.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-cas-anso', 'CAS-ANSO Scholarship (Degree Program)', 'CN', 'ANSO / Chinese Academy of Sciences (UCAS, USTC)', 'anso-cas', 'https://www.anso.org.cn/programmes/talent/scholarship/202510/t20251015_786021.html', '["master","phd"]', 'new', 'Tuition waiver; monthly stipend; health insurance; application fee waiver; international airfare (one trip to China and one-way return after normal study period); travel subsidy for language training. 100-200 Master''s and 300 PhD awards yearly. Stipend (as published): Master''s: RMB 3,000/month or RMB 6,000/month; PhD: RMB 6,000/month or RMB 7,000/month (depending on qualification test after 1 year)', '{}', 'Direct via UCAS (is.ucas.ac.cn) or USTC (isa.ustc.edu.cn) admission systems', '31st January 2026 (Beijing Time)', '2026/27', 'NEEDS_REVIEW', 0, '2026-10-25', 'Extraction tool; verify verbatim. 2026 results announced June 2026; 2027 call not yet published. Age cut-offs will shift for next cycle.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-shanghai-gov-a', 'Shanghai Government Scholarship - Category A (Full)', 'CN', 'Shanghai Municipal Government', 'shanghai-gov', 'https://english.shanghai.gov.cn/en-ApplyforScholarships/20240208/a21ea5f94b2f42959635d72308606778.html', '["bachelor","master","phd"]', 'both', 'Covers tuition, accommodation, living expenses, and comprehensive medical insurance for the duration of study. Amounts are in an image table (RMB per person per year) that could not be read.', '{}', 'Study in Shanghai platform, applying to a participating Shanghai university', 'Applications are generally accepted from February to April each year; specific period determined by each university', NULL, 'NEEDS_REVIEW', 0, '2026-10-25', 'Funding amounts in image - not extracted. HSK 4 general requirement may be a barrier for English-taught applicants; verify with universities. Extraction tool; verify verbatim.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('cn-shanghai-gov-b', 'Shanghai Government Scholarship - Category B (Partial)', 'CN', 'Shanghai Municipal Government', 'shanghai-gov', 'https://english.shanghai.gov.cn/en-ApplyforScholarships/20240208/a21ea5f94b2f42959635d72308606778.html', '["bachelor","master","phd"]', 'both', 'Covers tuition and comprehensive medical insurance fees for the duration of study.', '{}', 'Study in Shanghai platform, applying to a participating Shanghai university', 'Applications are generally accepted from February to April each year; specific period determined by each university', NULL, 'NEEDS_REVIEW', 0, '2026-10-25', 'Same page as Category A. Extraction tool; verify verbatim.', '2026-10-25T11:28:09.296Z');
