INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('de-daad-epos', 'DAAD Development-Related Postgraduate Courses (EPOS)', 'DE', 'DAAD', 'daad-database', 'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?detail=50076777', '["master","phd"]', 'new', 'Monthly payments, health/accident/personal liability insurance, travel allowance; possible rent subsidy and family allowance. Duration 12 to 42 months. Only for courses on the EPOS list (2027/2028 deadlines PDF). Stipend (as published): 992 euros for graduates or 1,300 euros (1,400 euros beginning with February 2026) for doctoral candidates', '{}', 'Direct to the chosen EPOS course (not DAAD portal)', 'Depending on chosen study programme; please check scholarship brochure or the website of your chosen study programme.', '2027/28', 'NEEDS_REVIEW', 0, '2026-10-25', 'Database detail page opened; listed on daad.pk Pakistan page. Tuition not covered on page; check per course. Course deadline PDF not opened. Some excerpts via extraction tool; verify verbatim.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('de-daad-research-grants', 'DAAD Research Grants in Germany (doctoral / early postdoc)', 'DE', 'DAAD', 'daad-database', 'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?origin=194&detail=57742121', '["phd"]', 'both', 'Monthly scholarship, health/accident/liability insurance, travel allowance, research allowance of 460 euros for over six months. Doctoral students 2-12 months; postdocs 2-6 months. Stipend (as published): monthly scholarship payments of 1.400 euros', '{}', 'DAAD portal', '31.08.2026 (selection February 2027; funding from May 2027 at the earliest)', '2027', 'NEEDS_REVIEW', 0, '2026-10-25', 'Opened with Pakistan origin filter (194). Deadline 31.08.2026 passed; next deadline usually end of August per daad.pk. Extraction tool; verify verbatim.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('de-daad-study-all-disciplines', 'DAAD Study Scholarships - Master Studies for All Academic Disciplines', 'DE', 'DAAD', 'daad-database', 'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?detail=50026200', '["master"]', 'new', 'Scholarship of 992 euros per month for 10 to 24 months of postgraduate study in Germany. Stipend (as published): Scholarship payments of 992 euros a month', '{}', 'DAAD portal (only for listed countries)', 'Application deadlines are updated annually in the second quarter; applications possible between 1 June and the stated deadline.', NULL, 'NEEDS_REVIEW', 0, '2026-10-25', 'With origin=194 (Pakistan) the extraction returned nothing; daad.pk lists only arts/architecture/music variants for Pakistan. Likely not open to Pakistan - reviewer must confirm.', '2026-10-25T11:28:09.296Z');
INSERT OR REPLACE INTO scholarships (id, name, country, provider, source_id, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_text, academic_year, status, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('de-daad-stem', 'DAAD Study Scholarships for STEM Disciplines', 'DE', 'DAAD', 'daad-database', 'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?origin=194&detail=57742130', '["master"]', 'new', 'Monthly scholarship for STEM Master''s in Germany, 10 to 24 months. Stipend (as published): monthly scholarship payments of 992 euros', '{}', 'DAAD portal', 'Application deadlines are updated annually in the second quarter; applications possible between 1 June and the stated deadline.', NULL, 'NEEDS_REVIEW', 0, '2026-10-25', 'Extraction tool reported Pakistan not in the country selector; not on daad.pk list either. Treat as probably NOT open to Pakistani applicants; verify manually.', '2026-10-25T11:28:09.296Z');
